// EduQuest Mascot & Rank Badge Assets (Transparent WebP Data URIs)
window.EDUQUEST_ASSETS = {
  "mascot": "data:image/webp;base64,",
  "rekrut": "data:image/webp;base64,",
  "penjelajah": "data:image/webp;base64,",
  "kesatria": "data:image/webp;base64,",
  "pahlawan": "data:image/webp;base64,",
  "legenda": "data:image/webp;base64,"
};
window.MASCOT_DATA_URI = window.EDUQUEST_ASSETS.mascot;

document.addEventListener('DOMContentLoaded', () => {
  const img = document.getElementById('mascot-img-choice');
  if (img) img.src = window.EDUQUEST_ASSETS.mascot;
  const heroMascot = document.getElementById('new-user-hero-mascot');
  if (heroMascot) heroMascot.src = window.EDUQUEST_ASSETS.mascot;
  const oldHeroBadge = document.getElementById('old-user-hero-badge');
  if (oldHeroBadge) oldHeroBadge.src = window.EDUQUEST_ASSETS.kesatria;
});
